vals = [str(x).strip().lower() for x in df.values.flatten() if pd.notnull(x) and str(x).strip()!='']
# Simple edit distance
def ed(a,b):
    dp=[[i for i in range(len(b)+1)]]
    dp+= [[i]+[0]*len(b) for i in range(1,len(a)+1)]
    for i in range(1,len(a)+1):
        for j in range(1,len(b)+1):
            dp[i][j]=min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+(a[i-1]!=b[j-1]))
    return dp[len(a)][len(b)]
items = sorted(set(vals))
near = {k:[] for k in ["turtle soup","hoagie"]}
for k in near:
    for it in items:
        if it!=k and ed(k,it)<=2:
            near[k].append(it)
